            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((comp, color))

    motif, motif_color = max(components, key=lambda item: len(item[0]))
    motif_set = set(motif)
    top = min(r for r, c in motif)
    bottom = max(r for r, c in motif)
    left = min(c for r, c in motif)
    height = bottom - top + 1
    mask = {(r - top, c - left) for r, c in motif}

    # Read the detached palette along its longer dimension.
    palette = [(r, c, grid[r][c])
               for r in range(h) for c in range(w)
               if grid[r][c] != 0 and (r, c) not in motif_set]
