    r1 = max(r for r, c, v in palette)
    c0 = min(c for r, c, v in palette)
    c1 = max(c for r, c, v in palette)

    colors = []
    if c1 - c0 >= r1 - r0:
        for c in range(c0, c1 + 1):
            vals = [v for r, x, v in palette if x == c]
            if vals:
                colors.append(max(set(vals), key=vals.count))
    else:
        for r in range(r0, r1 + 1):
            vals = [v for y, c, v in palette if y == r]
            if vals:
                colors.append(max(set(vals), key=vals.count))

